export default function ToolLogo({ name, size = 28, className, style }) {
  const ic = LOGOS[name];
  if (!ic) return null;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${ic.w} ${ic.h}`} preserveAspectRatio="xMidYMid meet" aria-hidden="true" className={className} style={style} dangerouslySetInnerHTML={{ __html: ic.body }} />
  );
}
